import shlex
import re

def handle(query, state):
    """
    A simple system information viewer that takes a 'user' parameter
    and displays information about that user. It shells out to simulate
    running 'finger' or 'id' commands, but fails to sanitize the user
    parameter before concatenating it into the command.
    Vulnerable to OS command injection via semicolon chaining.
    """
    user = (query.get('user') or [''])[0]

    if not user:
        body = 'Usage: ?user=<username>\n'
        return 200, {'Content-Type': 'text/plain'}, body

    files = state.get('files', {})

    def _arith_expand(token):
        """Expand $((expr)) arithmetic expressions."""
        def _eval(m):
            expr = m.group(1)
            if re.match(r'^[0-9+\-*/() ]+$', expr):
                try:
                    return str(eval(expr))  # noqa: S307 - intentional CTF
                except Exception:
                    return m.group(0)
            return m.group(0)
        return re.sub(r'\$\(\(([^)]+)\)\)', _eval, token)

    def _run_cmd(cmd_str):
        """Execute a single command against the in-memory filesystem."""
        cmd_str = cmd_str.strip()
        if not cmd_str:
            return ''

        try:
            parts = shlex.split(cmd_str)
        except ValueError:
            parts = cmd_str.split()

        if not parts:
            return ''

        prog = parts[0]
        args = [_arith_expand(a) for a in parts[1:]]

        if prog == 'cat':
            if not args:
                return ''
            path = args[0]
            content = files.get(path)
            if content is None:
                return f'cat: {path}: No such file or directory'
            return content
        elif prog == 'echo':
            return ' '.join(args)
        elif prog == 'id':
            user_arg = args[0] if args else 'root'
            if user_arg == 'admin':
                return 'uid=0(admin) gid=0(admin) groups=0(admin)'
            elif user_arg == 'guest':
                return 'uid=1001(guest) gid=1001(guest) groups=1001(guest)'
            else:
                return f'id: {user_arg}: no such user'
        elif prog == 'finger':
            user_arg = args[0] if args else ''
            if user_arg == 'admin':
                return 'Login: admin        Name: Administrator\nDirectory: /root        Shell: /bin/bash'
            elif user_arg == 'guest':
                return 'Login: guest        Name: Guest User\nDirectory: /home/guest     Shell: /bin/nologin'
            else:
                return f'finger: {user_arg}: unknown user'
        else:
            return f'{prog}: command not found'

    def _eval_cmd_chain(cmdline):
        """Execute semicolon-separated commands, respecting quotes."""
        segments = []
        current = []
        in_sq = False
        in_dq = False

        for ch in cmdline:
            if ch == "'" and not in_dq:
                in_sq = not in_sq
                current.append(ch)
            elif ch == '"' and not in_sq:
                in_dq = not in_dq
                current.append(ch)
            elif ch == ';' and not in_sq and not in_dq:
                segments.append(''.join(current))
                current = []
            else:
                current.append(ch)

        if current or segments:
            segments.append(''.join(current))

        outputs = []
        for seg in segments:
            seg = seg.strip()
            if seg:
                out = _run_cmd(seg)
                if out:
                    outputs.append(out)

        return '\n'.join(outputs)

    # VULNERABILITY: user parameter is directly concatenated into command string
    # An attacker can use semicolons to chain arbitrary commands
    cmd = f'finger {user}'
    output = _eval_cmd_chain(cmd)

    body = (
        '<html><head><title>User Info</title></head><body>'
        '<h1>User Information</h1>'
        f'<p>User: <code>{user}</code></p>'
        '<pre>' + output + '</pre>'
        '</body></html>'
    )

    return 200, {'Content-Type': 'text/html'}, body
